import{c as r,Q as o,j as t,m as a}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Maestro Order: A Model-Agnostic Orchestration Harness","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.23983","title":"Maestro Order: A Model-Agnostic Orchestration Harness","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.23983,"authors":["Hidayet Aksu"],"domains":["cs.CR","cs.AI","cs.LO","cs.MA"],"html":"https://arxiv.org/html/2606.23983v1","pdf_path":"pdfs/2606.23983.pdf","published_date":"2026-06-22T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-22-maestro-order-model-agnostic-orchestration-harness-2606-23983.md","filePath":"research/papers/2026-06-22-maestro-order-model-agnostic-orchestration-harness-2606-23983.md","lastUpdated":1785909234000}'),s={name:"research/papers/2026-06-22-maestro-order-model-agnostic-orchestration-harness-2606-23983.md"};function i(n,e,l,c,d,h){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="maestro-order-a-model-agnostic-orchestration-harness" tabindex="-1">Maestro Order: A Model-Agnostic Orchestration Harness <a class="header-anchor" href="#maestro-order-a-model-agnostic-orchestration-harness" aria-label="Permalink to &quot;Maestro Order: A Model-Agnostic Orchestration Harness&quot;">​</a></h1><p><strong>Authors</strong>: Hidayet Aksu <strong>Published</strong>: June 22, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.23983" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.23983</a> · <a href="https://arxiv.org/html/2606.23983v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.23983 <strong>Categories</strong>: cs.CR, cs.AI, cs.LO, cs.MA <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.23983" target="_blank" rel="noreferrer">research/papers/pdfs/2606.23983.pdf</a> (10 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>A single forward pass of a capable model is a fast, fluent, and unreliable problem-solver: it is right often enough to be useful and wrong often enough to be dangerous; in language models, such confident errors are known as hallucinations. We present Maestro Order, a model-agnostic orchestration harness that turns unreliable solvers into reliable problem-solving systems by composing them according to four structural primitives (decompose, ensemble, verify, and recurse) and a budget-aware controller that decides where to spend compute.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><p>把「單次 forward pass = 快但不可靠的 solver」視為待治理的元件，用 harness 層的結構化組合把不可靠 solver 變成可靠系統。四個結構 primitive + 預算感知 controller：</p><ol><li><strong>Decompose</strong> — 任務拆解為子問題。</li><li><strong>Ensemble</strong> — 多 solver 表決，僅在「高於隨機水準」時有益，且受 shared error 上限約束。</li><li><strong>Verify</strong> — verifier ensemble + 線上量測判別力；以 selective verification 在邊際「reliability-per-cost」最高處下注。</li><li><strong>Recurse</strong> — 對未通過的子問題遞迴投入算力。</li><li><strong>Budget-aware controller</strong> — 依邊際可靠度/成本比決定算力分配，把 solver 當 black box（model-agnostic）。</li></ol><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li><strong>Verification 幾何放大可靠度</strong>：0.55 →（2 gate）0.98 →（4 gate）0.999。</li><li><strong>Voting 僅在超隨機水準時有效</strong>，且被 solver 間相關錯誤封頂。</li><li><strong>Budget-aware controller</strong> 以遠低於 voting-only 的成本達到目標可靠度。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>失敗模式：verifier gaming（被驗證器博弈）、solver 間相關錯誤、decomposition 誤差累積。</li><li>需 robust checker + solver 多樣化才能維持放大效果。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>「判斷 vs 決定」直接背書</strong>：controller 與 verify/recurse 為確定性 orchestration，solver（LLM）只做 judgment——與 core.md 跨切紀律「LLM 判斷、確定性代碼決定」同構。</li><li><strong><code>unverified_success</code> 閘門的量化版</strong>：verification 幾何放大（0.55→0.999）= 「fresh-context verifier 優於 self-critique」+ 多道 gate 的數學論據；可作 <code>/pilot frontier</code> 稽核（原 quality-pipeline，v5.1 刪除） / <code>ship</code> S10 merge gate（原 verified-merge） 多 gate 設計參考。</li><li><strong><code>/pilot frontier</code> 稽核的成本模型</strong>（原 <code>/qp</code>、<code>/pilot-review</code>，v5.1 併入 <code>pilot</code>）：budget-aware「邊際 reliability-per-cost」分配，呼應 effort-first + model 階梯的成本紀律。</li><li>⚠️ 單作者短文（10 pp），結果偏理論化推導；落地需自建 verifier ensemble。</li></ul>',17)])])}const u=r(s,[["render",i]]);export{p as __pageData,u as default};
